// Import the Verus prelude (provides Vec, Seq, and the verifier attributes)
use verus::prelude::*;

/// Given an input Vec<char> of length ≥ 3, with:
///   • input[1] == ' '
///   • input[0] ∈ {'H','D'}
///   • input[2] ∈ {'H','D'}
///   • if input.len() > 3 then input[3] == '\n'
/// produce a two‐character Vec<char>:
///   • If input[0] == input[2], return ['H','\n']
///   • Otherwise, return ['D','\n']
///
/// We state pre- and post-conditions which the Verus verifier will check.
#[verus::requires(input.len() >= 3)]
#[verus::requires(input[1] == ' ')]
#[verus::requires(input[0] == 'H' || input[0] == 'D')]
#[verus::requires(input[2] == 'H' || input[2] == 'D')]
#[verus::requires(input.len() <= 3 || input[3] == '\n')]
#[verus::ensures(result.len() == 2)]
#[verus::ensures(result[1] == '\n')]
#[verus::ensures(result[0] == if input[0] == input[2] { 'H' } else { 'D' })]
pub fn solve(input: Vec<char>) -> Vec<char> {
    // Simple branch, no loops → no invariants or decreases needed.
    if input[0] == input[2] {
        vec!['H', '\n']
    } else {
        vec!['D', '\n']
    }
}

#[verus::proof]
fn test_solve() {
    // Examples to exercise the verifier:
    let a: Vec<char> = vec!['H',' ','H','\n'];
    let r = solve(a.clone());
    assert!(r == vec!['H','\n']);

    let b: Vec<char> = vec!['H',' ','D','\n'];
    let r2 = solve(b.clone());
    assert!(r2 == vec!['D','\n']);
}